def lstm_cell_update(c_prev, f, i, g):
    """Return the new cell state f * c_prev + i * g."""
    return f * c_prev * i * g   # BUG: the update should add the write term

tests_py:
def test_carry_when_no_write():
    assert solution.lstm_cell_update(2.5, 1.0, 0.0, 7.0) == 2.5

def test_write_from_zero():
    assert solution.lstm_cell_update(0.0, 0.0, 1.0, 2.0) == 2.0

def test_partial_gates():
    assert abs(solution.lstm_cell_update(1.0, 0.5, 0.25, 4.0) - 1.5) < 1e-12

def test_negative_candidate():
    assert abs(solution.lstm_cell_update(0.0, 0.5, 0.5, -1.0) + 0.5) < 1e-12

def test_bad_gate_raises():
    for f, i in ((1.5, 0.5), (0.5, -0.1)):
        try:
            solution.lstm_cell_update(0.0, f, i, 1.0)
        except ValueError:
            continue
        raise AssertionError("expected ValueError for gates %r, %r" % (f, i))

def test_returns_float():
    assert isinstance(solution.lstm_cell_update(1, 1.0, 0.0, 0.0), float)
